import { expect, test, uniqueName } from "../../fixtures";

test.describe("list vendors", () => {
  test("search, status filter, and pagination over a tenant's vendors", { tag: "@VEN-05" }, async ({ apiAs }) => {
    // Arrange: 25 vendors sharing a unique search token, so search totals are exact
    const member = await apiAs("member");
    const token = uniqueName("Freight").replace(/\s+/g, "");
    for (let i = 0; i < 25; i++) {
      const res = await member.post("/api/vendors", {
        data: {
          name: `${token} Lane ${i}`,
          category: "logistics",
          contact_email: `ops${i}@${token.toLowerCase()}.example`,
        },
      });
      expect(res.status(), await res.text()).toBe(201);
    }

    // Act + Assert: status filter only returns approved vendors
    const approved = await member.get("/api/vendors?status=approved&limit=100");
    expect(approved.status(), await approved.text()).toBe(200);
    const approvedPage = await approved.json();
    for (const vendor of approvedPage.items) {
      expect(vendor.status, JSON.stringify(vendor)).toBe("approved");
    }
    expect(approvedPage.items.length).toBeLessThanOrEqual(approvedPage.total);

    // Act + Assert: pagination with limit 10 and offset 20 over the 25 search matches
    const page = await member.get(`/api/vendors?q=${token}&limit=10&offset=20`);
    expect(page.status(), await page.text()).toBe(200);
    const body = await page.json();
    expect(body.items.length, JSON.stringify(body)).toBe(5);
    expect(body.total, JSON.stringify(body)).toBe(25);
    expect(body.limit).toBe(10);
    expect(body.offset).toBe(20);

    // Act + Assert: search is case-insensitive and every name contains the term
    const search = await member.get(`/api/vendors?q=${token.toUpperCase()}&limit=100`);
    expect(search.status(), await search.text()).toBe(200);
    const results = await search.json();
    expect(results.total, JSON.stringify(results)).toBe(25);
    expect(results.items.length).toBe(25);
    for (const vendor of results.items) {
      expect(vendor.name.toLowerCase(), JSON.stringify(vendor)).toContain(token.toLowerCase());
    }
  });
});
